/**
 * Real Good AI: site-wide loader for Squarespace.
 *
 * The footer code injection is just a config <script> (public values) plus one
 * <script type="module" src="…/site-loader.js">. This file is the single place that knows about
 * every widget. A Squarespace code block holds only a widget's tag (and attributes), for example
 * <rg-leaderboard></rg-leaderboard>; see docs/squarespace-snippets.md for every tag.
 *
 * Widget code is loaded LAZILY: a widget's chunk is downloaded only when its tag is on the page,
 * so a page without it never pays for it. The page is re-checked when Squarespace swaps pages
 * (`mercury:load`) and when tags are added later. The campaign pages (/fundraising-campaigns and
 * /fundraising-campaigns/p/<slug>) are routed by path: the loader replaces Squarespace's native
 * product UI there.
 */

import { createLazyLoader, watchPage, type LazyWidget } from './lazy-widgets';
import { isCampaignPagePath, isListingPath, showsAccountButton } from './routes';

console.log('[RGAI] Site-wide loader initialized.');

/** Every widget: the selector that means "this page needs it", and where its code is. */
export const WIDGETS: readonly LazyWidget[] = [
  { selector: 'rg-donation-form, rg-leaderboard, rg-recent-donations', load: () => import('./donations/index') },
  { selector: 'rg-bulb', load: () => import('./campaigns/bulb/rg-bulb') },
  { selector: 'rg-progress-bar', load: () => import('./campaigns/progress-bar') },
  { selector: 'rg-campaign-form', load: () => import('./campaign-form/rg-campaign-form') },
  { selector: 'rg-click-counter', load: () => import('./misc/click-counter/rg-click-counter') },
  { selector: 'rg-openrouter-chat', load: () => import('./misc/openrouter-chat/rg-openrouter-chat') },
  { selector: 'rg-real-rating', load: () => import('./misc/real-rating/rg-real-rating') },
  { selector: 'rg-youtube-shorts', load: () => import('./misc/youtube-shorts/rg-youtube-shorts') },
  // The story-review app mounts itself where its container is present.
  { selector: '#rgai-app, rgai-app', load: () => import('./story-review/index') },
];

const loader = createLazyLoader(
  WIDGETS,
  (selector) => document.querySelector(selector) !== null,
  (selector, err) => console.error(`[RGAI] could not load the code for "${selector}":`, err),
);

/** On a campaign page, replace Squarespace's native product UI with ours (once per page change). */
async function mountCampaignRoute(): Promise<void> {
  const path = window.location.pathname;
  if (!isCampaignPagePath(path)) return;
  // The listing shows tiles only; a detail page also shows the donation widgets, so it loads more.
  if (isListingPath(path)) await import('./campaigns/campaign-listing');
  else await import('./campaigns/index');
  const { mountCampaignPages } = await import('./campaigns/pages');
  mountCampaignPages();
}

/** The account button, placed into Squarespace's header, only on the pages listed in routes.ts (and only when the
 *  page has a header). Squarespace's own scripts may rebuild the header after load, so this runs on every DOM change
 *  (it is idempotent). Squarespace's AJAX navigation keeps the header, so on any other page a button left over from
 *  the previous page is removed. */
let accountButtonCode: Promise<typeof import('./account/header-mount')> | null = null;
function mountAccountButton(): void {
  if (!showsAccountButton(window.location.pathname)) {
    document.querySelectorAll('.rg-account-slot').forEach((slot) => slot.remove());
    return;
  }
  if (!document.querySelector('.header-display-desktop, .header-display-mobile')) return;
  accountButtonCode ??= Promise.all([import('./account/header-mount'), import('./account/rg-account-button')]).then(([m]) => m);
  accountButtonCode
    .then((m) => m.mountHeaderAccountButtons())
    .catch((err) => console.error('[RGAI] could not place the account button:', err));
}

function onPageChange(): void {
  void mountCampaignRoute();
  mountAccountButton();
}

watchPage(() => {
  loader.scan();
  mountAccountButton();
});
onPageChange();
window.addEventListener('mercury:load', () => {
  console.log('[RGAI] mercury:load event fired — re-checking the page.');
  onPageChange();
});
