// Which Squarespace page are we on? Production's paths; the loader uses them to decide what to load.

const DETAIL_PATH = /^\/fundraising-campaigns\/p\/([a-z0-9-]+)\/?$/;
const LISTING_PATH = '/fundraising-campaigns';

/** The campaign slug of a detail page (/fundraising-campaigns/p/<slug>), or null. */
export function detailSlug(pathname: string): string | null {
  return DETAIL_PATH.exec(pathname)?.[1] ?? null;
}

/** Is this the listing page (/fundraising-campaigns), with or without a trailing slash? */
export function isListingPath(pathname: string): boolean {
  return pathname.replace(/\/$/, '') === LISTING_PATH;
}

/** Does this path need the campaign page code (detail or listing)? */
export function isCampaignPagePath(pathname: string): boolean {
  return detailSlug(pathname) !== null || isListingPath(pathname);
}

/** The only pages that show the header account button for now: the four story-review pages (user's decision,
 *  2026-11-18). Every other page, /donate and the campaign pages included, stays as it was. */
export const ACCOUNT_BUTTON_PATHS: readonly string[] = ['/my-account', '/submit-a-story', '/review', '/review-admin'];

/** Does this page show the header account button? Exact paths, with or without a trailing slash. */
export function showsAccountButton(pathname: string): boolean {
  return ACCOUNT_BUTTON_PATHS.includes(pathname.replace(/(.)\/$/, '$1'));
}
