// Lazy loading of widget code. The site loader knows every widget's tag (or selector) but loads a
// widget's code only when its tag is on the page, so a page without a given widget never downloads it.
//
// The mechanism is a small pure core (testable without a browser): `createLazyLoader` takes the
// widget list, a `matches(selector)` question about the page, and a way to report errors.

export interface LazyWidget {
  /** A CSS selector: the widget is needed when anything on the page matches it. */
  selector: string;
  /** Loads the widget's module (which defines its custom elements as a side effect). */
  load: () => Promise<unknown>;
}

export interface LazyLoader {
  /** Load every widget whose selector matches the page and that is not loaded (or loading) yet. */
  scan(): void;
  /** Selectors whose code has been loaded successfully. */
  loaded(): string[];
}

/** A failing load is tried again on a later scan, but only a few times (a broken chunk must not loop forever). */
const MAX_ATTEMPTS = 3;

export function createLazyLoader(
  widgets: readonly LazyWidget[],
  matches: (selector: string) => boolean,
  onError: (selector: string, error: unknown) => void = () => {},
): LazyLoader {
  const state = new Map<string, { status: 'loading' | 'loaded' | 'failed'; attempts: number }>();
  return {
    scan() {
      for (const w of widgets) {
        const s = state.get(w.selector);
        if (s && (s.status === 'loading' || s.status === 'loaded')) continue;
        if (s && s.attempts >= MAX_ATTEMPTS) continue;
        if (!matches(w.selector)) continue;
        const attempts = (s?.attempts ?? 0) + 1;
        state.set(w.selector, { status: 'loading', attempts });
        w.load().then(
          () => state.set(w.selector, { status: 'loaded', attempts }),
          (err) => {
            state.set(w.selector, { status: 'failed', attempts });
            onError(w.selector, err);
          },
        );
      }
    },
    loaded: () => [...state.entries()].filter(([, s]) => s.status === 'loaded').map(([k]) => k),
  };
}

/**
 * Runs `fn` now, again when the document has finished loading, whenever Squarespace swaps the page
 * (`mercury:load`) and when elements are added to the page later (debounced).
 */
export function watchPage(fn: () => void): void {
  fn();
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', fn, { once: true });
  window.addEventListener('mercury:load', fn);
  let timer: ReturnType<typeof setTimeout> | undefined;
  new MutationObserver(() => {
    clearTimeout(timer);
    timer = setTimeout(fn, 60);
  }).observe(document.documentElement, { childList: true, subtree: true });
}
